import json
from datetime import datetime
from decimal import Decimal
def task_func(my_obj):
    class DateTimeEncoder(json.JSONEncoder):
        def default(self, obj):
            if isinstance(obj, datetime):
                return None  
            if isinstance(obj, Decimal):
                return str(obj)
            return json.JSONEncoder.default(self, obj)
    return json.dumps(my_obj, cls=DateTimeEncoder)

import seaborn as sns
import numpy as np
def task_func(df):
    if df.empty:
        raise ValueError("DataFrame is empty. Non-empty DataFrame required.")
    if df.select_dtypes(include=[np.number]).shape[1] != df.shape[1]:
        raise TypeError(
            "DataFrame contains non-numeric data. Only numeric data types are supported."
        )
    covariance_df = df.cov()

    pair_plot = sns.pairplot(df, markers=['o'], diag_kind='hist', hue='category')

    return covariance_df, pair_plot

import socket
from ipaddress import IPv4Network
from threading import Thread
def task_func(ip_range, port):

    ip_network = IPv4Network(ip_range)
    results = {}

    def check_port(ip):
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
                sock.settimeout(0.5)
                result = sock.connect_ex(('{}'.format(ip), port))
                if result == 0:
                    results[ip] = True
                else:
                    results[ip] = False
        except Exception as e:
            print(e)

    threads = []
    for ip in ip_network:
        thread = Thread(target=check_port, args=(ip,))
        thread.start()
        threads.append(thread)

    for thread in threads:
        thread.join()

    return results

import random
import string
POSSIBLE_LETTERS = ['a', 'b', 'c']
def task_func(word):
    if not word.isalpha():
        raise ValueError("Input contains non-letter characters.")

    pairs = []
    for i in range(len(word) - 1):
        pairs.append(word[i] + word[i+1])

    if len(pairs) < len(POSSIBLE_LETTERS):
        pairs += [''] * (len(POSSIBLE_LETTERS) - len(pairs))

    random.shuffle(pairs)
    return pairs[:len(POSSIBLE_LETTERS)]

